SELECT b.Id, b.CharacterProfileId, b.CurrentStep, b.Status, b.CanonicalFrontAssetId, b.CreatedUtc, b.UpdatedUtc, s.Step, s.Status AS StepStatus, s.OutputArtifactId, s.ManualOverrideApplied, s.ManualOverrideReason, s.ManualOverrideAuthor, s.MeasurementJson, s.FailureReason FROM CharacterIdentityBuilds b LEFT JOIN CharacterIdentityBuildSteps s ON s.BuildId=b.Id WHERE b.CharacterProfileId='f58f959a-8050-4388-a219-99d2df3446a1' ORDER BY b.UpdatedUtc DESC, s.Step;
